// Select Leads To Draft: pick Stage C (Master) rows that still need a draft.
// Read-only on approval: this node never touches human_approval.
const MAX_PER_RUN = 10;
const MIN_SCORE = 80;
const EMAIL_RE = /^[a-zA-Z0-9.!#$%&'*+/=?^_`{|}~-]+@[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?(?:\.[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?)+$/;
const BAD_EMAIL_STATUS = ['DISPOSABLE_WARNING', 'INVALID_SYNTAX', 'UNAVAILABLE'];
const clean = v => String(v == null ? '' : v).trim();

const out = [];
for (const it of $input.all()) {
  const r = it.json || {};
  const id = clean(r.master_lead_id);
  if (!id) continue;
  const status = clean(r.outreach_status).toUpperCase();
  if (status !== '' && status !== 'NOT_SENT') continue;      // DRAFTED / SENT / FAILED are never re-drafted
  if (clean(r.outreach_draft)) continue;                      // already has a draft
  const email = clean(r.verified_email);
  if (!EMAIL_RE.test(email)) continue;
  if (BAD_EMAIL_STATUS.includes(clean(r.email_status).toUpperCase())) continue;
  const contact = clean(r.contact_name);
  const company = clean(r.company_name);
  const evidenceText = clean(r.evidence);
  if (!contact || !company || !evidenceText) continue;
  const score = Number(clean(r.lead_score));
  if (!(score >= MIN_SCORE)) continue;
  out.push({ json: {
    master_lead_id: id,
    normalized_domain: clean(r.normalized_domain),
    company_name: company,
    contact_name: contact,
    designation: clean(r.designation),
    verified_email: email,
    headquarters_location: clean(r.headquarters_location),
    lead_score: score,
    evidence_text: evidenceText,
    evidence_lines: evidenceText.split(' | ').map(s => s.trim()).filter(Boolean).slice(0, 3)
  } });
  if (out.length >= MAX_PER_RUN) break;
}
return out;

// Build Draft Request: assemble the Groq chat-completions body (prompt = prompts/outreach.system.md).
const SYSTEM = "You write ONE short first-contact business email body for PranavX Labs, an automation studio that builds n8n workflow automations (for example automated lead research, reporting and follow-ups). Follow these rules exactly:\n1. Use ONLY the facts in the LEAD FACTS block. Never invent clients, results, numbers, prices, awards, meetings, mutual contacts or earlier contact.\n2. Do not write a greeting, sign-off, signature or footer. Code adds them. Write the body only.\n3. The body is two short paragraphs, 45 to 80 words in total. Paragraph 1: one specific, true observation taken from the EVIDENCE that shows the sender read their website, put in your own words (do not copy the evidence sentence word for word). Paragraph 2: one sentence on how workflow automation could save a company like theirs time, then one low-pressure question asking whether they would like a short note about it.\n4. evidence_used: copy ONE evidence line exactly as written (character for character, an exact substring of EVIDENCE, without the leading dash) that paragraph 1 is based on.\n5. No links, email addresses, phone numbers, emojis or exclamation marks. Do not use the words guarantee, urgent or act now, and do not offer anything for free.\n6. This is a first contact. Never write \"following up\", \"as discussed\" or \"re:\".\n7. subject: at most 8 words, plain and honest, contains the company name, no \"Re:\" or \"Fwd:\".\n8. Output JSON only. No markdown fences.";
const OFFER = 'PranavX Labs builds n8n workflow automations for small tech and web companies, such as automated lead research, reporting and follow-ups.';
const MAX_LINE = 300;

return $input.all().map(it => {
  const l = it.json;
  const facts = [
    'LEAD FACTS',
    'COMPANY: ' + l.company_name,
    'CONTACT: ' + l.contact_name + (l.designation ? ', ' + l.designation : ''),
    l.headquarters_location ? 'LOCATION: ' + l.headquarters_location : null,
    'OFFER: ' + OFFER,
    'EVIDENCE:',
    ...l.evidence_lines.map(s => '- ' + s.slice(0, MAX_LINE))
  ].filter(x => x !== null).join('\n');
  return { json: { ...l, request_body: {
    model: 'openai/gpt-oss-120b',
    temperature: 0.2,
    reasoning_effort: 'low',
    max_completion_tokens: 1200,
    messages: [
      { role: 'system', content: SYSTEM },
      { role: 'user', content: facts }
    ],
    response_format: { type: 'json_schema', json_schema: { name: 'outreach_draft', strict: true, schema: {
      type: 'object', additionalProperties: false,
      required: ['subject', 'body', 'evidence_used'],
      properties: { subject: { type: 'string' }, body: { type: 'string' }, evidence_used: { type: 'string' } }
    } } }
  } } };
});

// Verify & Assemble Draft: deterministic checks on the model output, then build the full email text.
// Pairs each Groq response with its lead by position (Groq Draft keeps item order, even on errors).
const SENDER_NAME = 'Anurag';
const SENDER_ROLE = 'AI Automation Intern';
const SENDER_COMPANY = 'PranavX Labs';
// NFR-07: replace with the full physical postal address of PranavX Labs before any real send.
const SENDER_ADDRESS = 'Maharashtra, India';
const BODY_MIN_WORDS = 35, BODY_MAX_WORDS = 90, EMAIL_MAX_WORDS = 119;

const fold = s => String(s == null ? '' : s).normalize('NFKC')
  .replace(/[‐-―−]/g, '-').replace(/[‘’]/g, "'").replace(/[“”]/g, '"')
  .replace(/\s+/g, ' ').trim().toLowerCase();
const words = s => String(s || '').trim().split(/\s+/).filter(Boolean).length;
const istNow = () => new Date(Date.now() + 5.5 * 3600 * 1000).toISOString().slice(0, 19).replace('T', ' ') + ' IST';

const BANNED = /\b(guarantee[sd]?|urgent|act now|limited time|for free|free (?:of charge|audit|consultation|trial|quote|assessment|demo|report|call|advice|ebook|guide|session)|following up|follow up|as discussed|per our|our call|our meeting|last week|you recently)\b|100%|\bre:|\bfwd?:/i;
const UNSUPPORTED_TERMS = ['award', 'trusted by', 'clients such as', 'case stud', 'ranked', 'top-rated', 'certified', 'partner of'];

const leads = $('Build Draft Request').all().map(x => x.json);
const results = $input.all().map(x => x.json);

return leads.map((lead, i) => {
  const res = results[i] || {};
  const reasons = [];
  let draft = null;

  if (res.error) {
    reasons.push('GROQ_ERROR: ' + String((res.error && res.error.message) || res.error).slice(0, 120));
  } else {
    const choice = res.choices && res.choices[0];
    if (!choice) reasons.push('NO_COMPLETION');
    else {
      if (choice.finish_reason && choice.finish_reason !== 'stop') reasons.push('INCOMPLETE_' + String(choice.finish_reason).toUpperCase());
      const raw = String((choice.message && choice.message.content) || '').trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '');
      try { draft = JSON.parse(raw); } catch (e) { reasons.push('BAD_JSON'); }
    }
  }

  let subject = '', body = '', evUsed = '';
  if (draft) {
    const dash = s => s.replace(/[\u2010-\u2015\u2212]/g, '-');   // model likes non-breaking hyphens
    subject = typeof draft.subject === 'string' ? dash(draft.subject.trim()) : '';
    body = typeof draft.body === 'string' ? dash(draft.body).split(/\n+/).map(s => s.trim()).filter(Boolean).join('\n\n') : '';
    evUsed = typeof draft.evidence_used === 'string' ? draft.evidence_used.trim().replace(/^[\s\-\u2022*]+/, '') : '';   // tolerate the bullet dash
    if (!subject || !body || !evUsed) reasons.push('MISSING_FIELD');
  }

  const factsFold = fold([lead.evidence_text, lead.company_name, lead.contact_name, lead.designation, lead.headquarters_location].join(' '));

  if (draft && reasons.length === 0) {
    // subject
    if (subject.length > 80 || words(subject) > 10 || /[\r\n]/.test(subject)) reasons.push('SUBJECT_TOO_LONG');
    const tok = String(lead.company_name || '').split(/[\s,.\-|&]+/).find(w => w.length >= 3 && !['the', 'pvt', 'ltd', 'llp', 'private', 'limited', 'and'].includes(w.toLowerCase()));
    if (tok && !fold(subject).includes(tok.toLowerCase())) reasons.push('SUBJECT_MISSING_COMPANY');
    // body length
    const bw = words(body);
    if (bw < BODY_MIN_WORDS) reasons.push('BODY_TOO_SHORT(' + bw + ')');
    if (bw > BODY_MAX_WORDS) reasons.push('BODY_TOO_LONG(' + bw + ')');
    // forbidden content
    const text = subject + '\n' + body;
    if (/https?:\/\/|www\.|\S+@\S+\.\S+|\+?\d[\d\s-]{8,}\d/i.test(text)) reasons.push('CONTAINS_LINK_EMAIL_OR_PHONE');
    if (/!/.test(text) || /[\u{1F300}-\u{1FAFF}\u{2600}-\u{27BF}]/u.test(text)) reasons.push('CONTAINS_EXCLAMATION_OR_EMOJI');
    if (BANNED.test(text)) reasons.push('BANNED_PHRASE');
    // grounding: the quoted evidence must be real, and the body may not add numbers or claims
    const ev = fold(evUsed);
    if (ev.length < 25 || !fold(lead.evidence_text).includes(ev)) reasons.push('EVIDENCE_NOT_VERBATIM');
    const nums = (body.replace(/\bn8n\b/gi, '').match(/\d[\d,.]*/g) || []).map(n => n.replace(/[.,]+$/, ''));
    if (nums.some(n => !factsFold.includes(n))) reasons.push('UNSUPPORTED_NUMBER');
    const bf = fold(body);
    if (UNSUPPORTED_TERMS.some(t => bf.includes(t) && !factsFold.includes(t))) reasons.push('UNSUPPORTED_CLAIM');
  }

  let emailText = '', ok = false, total = 0;
  if (draft && reasons.length === 0) {
    const first = String(lead.contact_name).replace(/^(mr|mrs|ms|dr)\.?\s+/i, '').trim().split(/\s+/)[0];
    const greeting = 'Hello ' + first + ',';
    const signoff = 'Regards,\n' + SENDER_NAME + '\n' + SENDER_ROLE + ', ' + SENDER_COMPANY;
    total = words(greeting) + words(body) + words(signoff);
    if (total > EMAIL_MAX_WORDS) reasons.push('EMAIL_OVER_120_WORDS(' + total + ')');
    else {
      const footer = '--\n' + SENDER_COMPANY + ' | ' + SENDER_ADDRESS + '\nThis is a one-time business enquiry sent to a publicly listed business address. To opt out of future messages, reply with UNSUBSCRIBE.';
      emailText = [greeting, '', body.replace(/\r\n/g, '\n'), '', signoff, '', footer].join('\n');
      ok = true;
    }
  }

  return { json: {
    master_lead_id: lead.master_lead_id,
    company_name: lead.company_name,
    verified_email: lead.verified_email,
    outreach_subject: ok ? subject : '',
    outreach_draft: ok ? emailText : '',
    outreach_status: ok ? 'DRAFTED' : 'NOT_SENT',
    drafted_at: ok ? istNow() : '',
    draft_notes: ok ? 'OK words=' + total : reasons.join('; ')
  } };
});
